// Ported from the Node app's Sequelize model Room (first generated by tools/gen-efcore.mjs).
using System.Text.Json.Nodes;
using System.Text.Json.Serialization;
using SchoolERP.Domain.Common;

namespace SchoolERP.Domain.Entities;

/// <summary>Table <c>rooms</c>.</summary>
public class Room : AuditableEntity
{
    public int Id { get; set; }
    public string Name { get; set; } = null!;
    public string Kind { get; set; } = "classroom";
    public int? Capacity { get; set; }

    [JsonIgnore]
    public ICollection<TimetableSlot> TimetableSlots { get; set; } = new List<TimetableSlot>();
    [JsonIgnore]
    public ICollection<RoomBooking> RoomBookings { get; set; } = new List<RoomBooking>();
}
